  `label` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `window_label` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `delivery_day` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'same_day',
  `start_time` time NOT NULL,
  `end_time` time NOT NULL,
  `cutoff_time` time NOT NULL,
  `capacity` int unsigned NOT NULL DEFAULT '25',
