  `prep_buffer_minutes` int unsigned DEFAULT NULL,
  `booking_cutoff_minutes` int unsigned DEFAULT NULL,
  `max_distance_km` decimal(8,2) DEFAULT NULL,
  `allowed_provider_slugs_json` json DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_delivery_slots_slug` (`slug`)
) ENGINE=InnoDB AUTO_INCREMENT=902 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
