INSERT INTO `notification_templates` VALUES (1,'payment.success.email','payment.success','email','Payment received — order {{order_number}}','<p>Hi {{customer_name}},</p><p>We received your payment of ₹{{amount}} for order <strong>{{order_number}}</strong>.</p>','Hi {{customer_name}}, we received your payment of Rs {{amount}} for order {{order_number}}.',NULL,NULL,NULL,1,'2026-11-02 06:00:13',NULL),(2,'payment.failed.email','payment.failed','email','Payment issue — order {{order_number}}','<p>Hi {{customer_name}},</p><p>Your payment for order {{order_number}} could not be completed. You can retry from your account.</p>','Payment for order {{order_number}} could not be completed. Please retry from your account.',NULL,NULL,NULL,1,'2026-11-02 06:00:13',NULL),(3,'support.ticket_created.email','support.ticket_created','email','Support ticket {{ticket_number}} received','<p>Hi {{customer_name}},</p><p>We received your support request ({{ticket_number}}). Our team will respond soon.</p>','We received your support ticket {{ticket_number}}.',NULL,NULL,NULL,1,'2026-11-02 06:00:13',NULL),(4,'support.ticket_replied.email','support.ticket_replied','email','Update on ticket {{ticket_number}}','<p>Hi {{customer_name}},</p><p>There is a new reply on your support ticket {{ticket_number}}.</p>','New reply on support ticket {{ticket_number}}.',NULL,NULL,NULL,1,'2026-11-02 06:00:13',NULL),(5,'support.ticket_created.in_app','support.ticket_created','in_app',NULL,NULL,NULL,NULL,'Support ticket opened','Ticket {{ticket_number}} was created.',1,'2026-11-02 06:00:13',NULL),(6,'refund.status_updated.email','refund.status_updated','email','Refund update — {{request_number}}','<p>Hi {{customer_name}},</p><p>Your refund request {{request_number}} status is now: {{status_label}}.</p>','Refund {{request_number}} status: {{status_label}}.',NULL,NULL,NULL,1,'2026-11-02 06:00:13',NULL);
