INSERT INTO `products` VALUES (1,1,'Fresh Red Tomatoes','fresh-red-tomatoes','VEG-TOM-001','Locally sourced tomatoes for daily cooking.','Selected for firmness and colour. Store in a cool, dry place away from direct sunlight. Wash before use.','fresh','published',1,1,0,0,NULL,NULL,1,'2026-10-30 10:12:20','2026-11-02 09:52:03'),(2,1,'Green Capsicum','green-capsicum','VEG-CAP-002','Crisp capsicum for stir-fry and stuffing.','Handled with care to reduce bruising. Rinse and pat dry before storing.','fresh','published',0,0,1,0,NULL,NULL,1,'2026-10-30 10:12:20','2026-10-30 10:12:20'),(3,1,'Red Onion','onion-red','VEG-ONI-003','Staple onion for Indian cooking.','Store in a ventilated basket away from potatoes.','fresh','published',0,1,0,0,NULL,NULL,1,'2026-10-30 10:12:20','2026-10-30 10:12:20'),(4,2,'Banana (Robusta)','banana-robusta','FRT-BAN-010','Ripe bananas for snacking and shakes.','Ripeness may vary; consume within recommended days after delivery.','fresh','published',1,0,0,0,NULL,NULL,1,'2026-10-30 10:12:20','2026-10-30 10:12:20'),(5,2,'Apple (Shimla)','apple-shimla','FRT-APL-011','Sweet-tart apples.','Refrigerate for longer shelf life.','fresh','published',0,0,1,0,NULL,NULL,1,'2026-10-30 10:12:20','2026-10-30 10:12:20'),(6,3,'Cut Mixed Salad Pack','cut-mixed-salad','CUT-SAL-020','Ready-cut salad vegetables — prepare fresh.','Prepared in small batches. Use within use-by guidance on pack. Keep refrigerated.','cut','published',1,1,0,0,NULL,NULL,1,'2026-10-30 10:12:20','2026-10-30 10:12:20'),(7,3,'Cut French Beans','cut-french-beans','CUT-FB-021','Trimmed beans ready to cook.','Refrigerate immediately. Do not freeze unless label allows.','cut','published',0,0,0,0,NULL,NULL,1,'2026-10-30 10:12:20','2026-10-30 10:12:20'),(8,4,'Homestyle Mango Pickle','mango-pickle-homestyle','PKL-MNG-030','Traditional mango pickle — packed food.','Ingredients and allergen info must match actual label at launch.','packaged','published',0,1,0,0,NULL,NULL,1,'2026-10-30 10:12:20','2026-10-30 10:12:20'),(9,4,'Moong Papad','papad-moong','PPD-MNG-031','Roast or fry at home.','Store in airtight container once opened.','packaged','published',0,0,0,0,NULL,NULL,1,'2026-10-30 10:12:20','2026-10-30 10:12:20'),(51,36,'AT-SEO13 Product b15fd0ec','at-seo13-prod-b15fd0ec','AT-SEO13-SKU-b15fd0ec','Short AT-SEO13 product blurb.','Long description ignored when meta set.','fresh','published',0,0,0,0,NULL,NULL,0,'2026-11-03 08:10:45','2026-11-03 08:10:45');
