--
-- Table structure for table `subscription_substitution_payments`
--

DROP TABLE IF EXISTS `subscription_substitution_payments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `subscription_substitution_payments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `substitution_id` bigint unsigned NOT NULL,
  `customer_subscription_id` bigint unsigned NOT NULL,
  `gateway` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'simulate',
  `amount` decimal(12,2) NOT NULL,
  `currency` char(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'INR',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'created',
  `idempotency_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `gateway_order_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gateway_payment_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gateway_event_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `metadata_json` json DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sub_subst_pay_idempotency` (`idempotency_key`),
  UNIQUE KEY `uq_sub_subst_pay_substitution` (`substitution_id`),
  KEY `fk_sspay_sub` (`customer_subscription_id`),
  CONSTRAINT `fk_sspay_sub` FOREIGN KEY (`customer_subscription_id`) REFERENCES `customer_subscriptions` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_sspay_substitution` FOREIGN KEY (`substitution_id`) REFERENCES `subscription_basket_substitutions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1746 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

